let csrfToken="", activeProject="", projects=[], toastTimer, myPermissions=[], currentUsername="";
const permissionLabels={view_dashboard:"View dashboard",manage_projects:"Manage projects",view_devices:"View camera sources",manage_devices:"Add or classify camera sources",run_discovery:"Configure and run discovery",view_people:"View people records",manage_people:"Manage people records",view_movement:"View movement events",view_alerts:"View review queue",review_alerts:"Create and review alerts",view_automation:"View automation events",view_audit:"View audit log",manage_users:"Manage accounts",manage_backups:"Create and download backups"};
const $=id=>document.getElementById(id);
function esc(value){return String(value??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(message){const el=$("toast");el.textContent=message;el.style.display="block";clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display="none",3200)}
function showLogin(){ $("login").classList.add("show");$("application").classList.add("hidden"); }
function showApp(){ $("login").classList.remove("show");$("application").classList.remove("hidden"); }
function modal(id){$(id).classList.add("open")};function closeModal(id){$(id).classList.remove("open")}
function can(p){const implied={view_devices:"manage_devices",view_people:"manage_people",view_alerts:"review_alerts"};return myPermissions.includes(p)||myPermissions.includes(implied[p])}
function applyPermissions(){document.querySelectorAll("[data-permission]").forEach(el=>el.classList.toggle("hidden",!can(el.dataset.permission)));$("signedInAs").textContent=currentUsername?"Signed in: "+currentUsername:"";const first=document.querySelector(".nav button:not(.hidden)");if(first&&!document.querySelector(".nav button.active:not(.hidden)"))go(first.dataset.view)}
function go(name){const button=document.querySelector('.nav button[data-view="'+name+'"]');if(button?.classList.contains("hidden"))return;document.querySelectorAll(".view").forEach(v=>v.classList.toggle("active",v.id===`view-${name}`));document.querySelectorAll(".nav button").forEach(b=>b.classList.toggle("active",b.dataset.view===name));const menuToggle=$("mobileMenuToggle"),menuAside=document.querySelector(".shell>aside");if(menuToggle){menuToggle.setAttribute("aria-expanded","false");menuToggle.setAttribute("aria-label","Open navigation menu")}menuAside?.classList.remove("mobile-menu-open");$("currentView").textContent=({overview:"Overview",devices:"Camera sources",people:"People records",alerts:"Review Studio",ai:"Staff alert drafting",audit:"Audit log",system:"System settings",movement:"Movement monitoring",automation:"Automation events",accounts:"Accounts and permissions",backups:"Backups"})[name]||name;window.scrollTo(0,0);if(name==="overview"||name==="movement")loadMovements();if(name==="automation")loadOutbox();if(name==="system")loadDiscoverySettings();if(name==="accounts")loadUsers();if(name==="backups")loadBackups();if(name==="ai")loadOpenAIStatus()}
window.go=go;window.modal=modal;window.closeModal=closeModal;

async function api(path,{method="GET",body=null,project=true}={}){
  const headers={"Accept":"application/json"};if(body!==null)headers["Content-Type"]="application/json";if(csrfToken&&method!=="GET")headers["X-CSRF-Token"]=csrfToken;if(project&&activeProject)headers["X-Casino-Project"]=activeProject;
  const response=await fetch(path,{method,headers,body:body===null?undefined:JSON.stringify(body),credentials:"same-origin"});let data={};try{data=await response.json()}catch{}
  if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data;
}
async function initialize(){
  try{const bootstrapResponse=await fetch("/api/bootstrap",{cache:"no-store"});if(!bootstrapResponse.ok)throw new Error("Setup status is unavailable");const bootstrap=await bootstrapResponse.json();if(typeof bootstrap.admin_ready!=="boolean")throw new Error("Setup status is invalid");if(!bootstrap.admin_ready){showLogin();$("loginForm").classList.add("hidden");$("setupForm").classList.remove("hidden");return}
    $("setupForm").classList.add("hidden");$("loginForm").classList.remove("hidden");
    try{await loadMe();applyPermissions();showApp();await loadProjects()}catch{showLogin()}
  }catch{showLogin();$("loginError").textContent="The local service is unavailable. Start it with the instructions in README.md."}
}
$("loginForm").addEventListener("submit",async e=>{e.preventDefault();$("loginError").textContent="";try{const result=await api("/api/login",{method:"POST",body:{username:$("loginUser").value.trim(),password:$("loginPass").value},project:false});csrfToken=result.csrf_token;await loadMe();$("loginPass").value="";showApp();await loadProjects()}catch(err){$("loginError").textContent=err.message}});
$("setupForm").addEventListener("submit",async e=>{e.preventDefault();$("setupError").textContent="";const username=$("setupUser").value.trim(),password=$("setupPass").value;try{await api("/api/setup",{method:"POST",body:{username,password},project:false});const result=await api("/api/login",{method:"POST",body:{username,password},project:false});csrfToken=result.csrf_token;await loadMe();$("setupPass").value="";showApp();await loadProjects();toast("Local administrator created.")}catch(err){$("setupError").textContent=err.message}});
$("logoutBtn").addEventListener("click",async()=>{try{await api("/api/logout",{method:"POST",body:{}})}catch{}csrfToken="";activeProject="";showLogin()});

async function loadMe(){const me=await api("/api/me",{project:false});csrfToken=me.csrf_token;myPermissions=me.permissions||[];currentUsername=me.username;applyPermissions()}
async function loadProjects(){
  projects=await api("/api/projects",{project:false});if(!projects.length)throw new Error("No CCTV project is available.");
  if(!projects.some(p=>String(p.id)===String(activeProject)))activeProject=String(projects[0].id);
  const select=$("projectSelect");select.innerHTML=projects.map(p=>`<option value="${p.id}">${esc(p.name)}${p.location?` · ${esc(p.location)}`:""}</option>`).join("");select.value=activeProject;await loadAll();
}
$("projectSelect").addEventListener("change",async()=>{activeProject=$("projectSelect").value;await loadAll();go("overview")});
document.querySelectorAll(".nav button").forEach(button=>button.addEventListener("click",()=>go(button.dataset.view)));$("mobileMenuToggle").addEventListener("click",()=>{const aside=document.querySelector(".shell>aside"),open=!aside.classList.contains("mobile-menu-open");aside.classList.toggle("mobile-menu-open",open);$("mobileMenuToggle").setAttribute("aria-expanded",String(open));$("mobileMenuToggle").setAttribute("aria-label",open?"Close navigation menu":"Open navigation menu")});document.addEventListener("keydown",event=>{if(event.key==="Escape"){document.querySelector(".shell>aside")?.classList.remove("mobile-menu-open");$("mobileMenuToggle").setAttribute("aria-expanded","false");$("mobileMenuToggle").setAttribute("aria-label","Open navigation menu")}});document.addEventListener("click",event=>{const aside=document.querySelector(".shell>aside");if(aside?.classList.contains("mobile-menu-open")&&!aside.contains(event.target)){aside.classList.remove("mobile-menu-open");$("mobileMenuToggle").setAttribute("aria-expanded","false");$("mobileMenuToggle").setAttribute("aria-label","Open navigation menu")}});

async function loadAll(){
  try{
    const jobs=[];
    if(can("view_devices"))jobs.push(api("/api/devices").then(rows=>{renderDevices(rows);renderDiscovered(rows);fillScanDevices(rows);if($("countDevices"))$("countDevices").textContent=rows.length;return ["devices",rows]}));
    if(can("view_people"))jobs.push(Promise.all([api("/api/people"),api("/api/presence")]).then(([rows,presence])=>{renderPeople(rows);renderPresence(presence);if($("countPeople"))$("countPeople").textContent=rows.length;return ["people",{rows,presence}]}));
    if(can("view_movement"))jobs.push(api("/api/movements").then(rows=>["movements",rows]));
    if(can("view_alerts"))jobs.push(api("/api/alerts").then(rows=>{renderAlerts(rows);if($("countAlerts"))$("countAlerts").textContent=rows.filter(a=>a.status==="Needs review").length;return ["alerts",rows]}));
    if(can("view_audit"))jobs.push(api("/api/audit").then(rows=>{renderAudit(rows);return ["audit",rows]}));
    if(can("view_automation"))jobs.push(api("/api/automation/outbox").then(rows=>{renderOutbox(rows);return ["outbox",rows]}));
    const results=Object.fromEntries(await Promise.all(jobs));
    if(can("view_dashboard"))renderOverview(results.devices||[],results.alerts||[],results.people?.rows||[],results.people?.presence||[],results.movements||[]);
    if(can("manage_users"))await loadUsers();
    if(can("manage_backups"))await loadBackups();
  }catch(err){toast(err.message)}
}
function statePill(value){const cls={Active:"ok",Configured:"ok",Reviewed:"ok",Identified:"ok",Dismissed:"",Escalated:"alert",Alert:"alert","Pending review":"wait","Needs review":"wait","Under review":"wait","Needs verification":"wait",Unverified:""}[value]||"";return `<span class="pill ${cls}">${esc(value)}</span>`}
function typeSelect(d){return `<select aria-label="Classify ${esc(d.name)}" onchange="classifyDevice(${d.id},this.value)">${["Unknown","DVR","NVR","Camera"].map(k=>`<option ${d.device_kind===k?"selected":""}>${k}</option>`).join("")}</select>`}
function renderDevices(rows){const q=($("deviceSearch")?.value||"").toLowerCase();rows=rows.filter(d=>Object.values(d).join(" ").toLowerCase().includes(q));$("deviceRows").innerHTML=rows.length?rows.map(d=>`<tr><td><b>${esc(d.name)}</b></td><td>${typeSelect(d)}</td><td>${esc(d.vendor_model||"—")}</td><td>${esc(d.host)}</td><td>${esc(d.port)}</td><td>${esc(d.protocol)}</td><td>${esc(d.source_mode||"Recorder")}</td><td>${esc(d.stream_label||"—")}</td><td>${esc(d.coverage_role||"General")}</td><td>${esc(Array.isArray(d.monitoring_purposes)?d.monitoring_purposes.join(" · "):"")||"—"}</td><td>${statePill(d.status)}</td></tr>`).join(""):'<tr><td colspan="11" class="empty">No sources yet. Add each DVR/NVR separately, then label its camera channels.</td></tr>';}
function renderDiscovered(rows){rows=rows.filter(d=>(d.stream_label||"").includes("Discovery candidate"));$("discoveredRows").innerHTML=rows.length?rows.map(d=>`<article class="lane-card"><div><strong>${esc(d.host)}</strong><small>${esc(d.protocol)} · port ${esc(d.port)} · ${d.device_kind==="DVR"||d.device_kind==="NVR"?"Eligible after connection setup":"Inventory until classified"}</small></div><div>${typeSelect(d)}</div></article>`).join(""):'<div class="empty">No discovery candidates yet.</div>'}
async function classifyDevice(id,device_kind){try{await api(`/api/devices/${id}`,{method:"PATCH",body:{device_kind}});toast(`Device classified as ${device_kind}. No connection was made.`);await loadAll()}catch(e){toast(e.message)}}window.classifyDevice=classifyDevice;
$("deviceSearch").addEventListener("input",()=>api("/api/devices").then(renderDevices).catch(e=>toast(e.message)));
function renderPeople(rows){const q=($("peopleSearch")?.value||"").toLowerCase(),f=$("peopleFilter")?.value||"";rows=rows.filter(p=>(!f||p.category===f)&&Object.values(p).join(" ").toLowerCase().includes(q));$("peopleRows").innerHTML=rows.length?rows.map(p=>{const presence=p.presence_status==="Checked out"?"Checked out":p.presence_status==="Returned"?"On site":"Not recorded";const presenceAction=p.category==="Staff"||p.category==="Manager"?p.status==="Active"?`<button class="btn" data-presence-person="${p.id}" data-presence-status="${p.presence_status==="Checked out"?"Returned":"Checked out"}">${p.presence_status==="Checked out"?"Record return":"Record check-out"}</button>`:"":"";return `<article class="person-card">${p.photo_mime?`<img src="/api/people/${p.id}/photo?project=${encodeURIComponent(activeProject)}" alt="">`:'<div class="photo-empty" aria-label="No photo">♙</div>'}<div><strong>${esc(p.display_name)}</strong><small>${esc(p.category)}${p.position?` · ${esc(p.position)}`:""}</small><small>${statePill(p.status)} ${statePill(presence)}</small></div><div class="presence-actions"><button class="btn" data-photo-person="${p.id}">${p.photo_mime?"Change photo":"Add photo"}</button>${presenceAction}${p.status==="Active"?`<button class="btn" onclick="setPersonStatus(${p.id},'Inactive')">Deactivate</button>`:`<button class="btn primary" onclick="activatePerson(${p.id},'${esc(p.category)}')">Approve</button>`}${can("manage_users")?`<button class="btn" onclick="removePerson(${p.id})">Delete</button>`:""}</div></article>`}).join(""):'<div class="empty">No people are saved yet.</div>'}
function renderPresence(rows){$("presenceRows").innerHTML=rows.length?rows.map(e=>`<tr><td>${esc(e.occurred_at)}</td><td>${esc(e.display_name)}</td><td>${statePill(e.status)}</td><td>${esc(e.actor)}</td><td>${esc(e.note||"—")}</td></tr>`).join(""):'<tr><td colspan="5" class="empty">No check-out or return entries recorded yet.</td></tr>'};function startPeopleImport(){go("people");$("peopleImportFile").click()}window.startPeopleImport=startPeopleImport;
$("peopleRows").addEventListener("click",async event=>{const photo=event.target.closest("[data-photo-person]");if(photo){$("peoplePhotoFile").dataset.personId=photo.dataset.photoPerson;$("peoplePhotoFile").click();return}const presence=event.target.closest("[data-presence-person]");if(presence){const action=presence.dataset.presenceStatus;if(!confirm(`Record ${action.toLowerCase()} for this staff member using the current time?`))return;const note=prompt("Optional brief note:")||"";try{await api("/api/presence",{method:"POST",body:{person_id:Number(presence.dataset.presencePerson),status:action,note}});toast(`${action} recorded with current time.`);await loadAll()}catch(e){toast(e.message)}}});
$("peoplePhotoFile").addEventListener("change",async event=>{const file=event.target.files[0],personId=event.target.dataset.personId;event.target.value="";if(!file||!personId)return;if(!isRosterPhoto(file)){toast("Choose a JPEG or PNG photo up to 5 MB.");return}try{await uploadProfilePhoto(personId,file);toast("Photo stored. This does not add an Overview record.");await loadAll()}catch(e){toast(e.message)}});
$("peopleSearch").addEventListener("input",()=>api("/api/people").then(renderPeople).catch(e=>toast(e.message)));$("peopleFilter").addEventListener("change",()=>api("/api/people").then(renderPeople).catch(e=>toast(e.message)));
async function activatePerson(id,category){let approval_note="";if(category==="Watchlist"){approval_note=prompt("Enter the documented approval reference for activating this watchlist record:")||"";if(!approval_note)return}try{await api(`/api/people/${id}`,{method:"PATCH",body:{status:"Active",approval_note}});toast("Record approved. Overview was not changed.");await loadAll()}catch(e){toast(e.message)}}
async function setPersonStatus(id,status){try{await api(`/api/people/${id}`,{method:"PATCH",body:{status}});toast(status==="Inactive"?"Record deactivated. Overview was not changed.":"Status saved. Overview was not changed.");await loadAll()}catch(e){toast(e.message)}}
async function removePerson(id){if(!confirm("Delete this staff, manager, or whitelist record and its stored photo? Only an administrator can do this."))return;try{await api(`/api/people/${id}`,{method:"DELETE"});toast("People record deleted.");await loadAll()}catch(e){toast(e.message)}}
window.activatePerson=activatePerson;window.setPersonStatus=setPersonStatus;window.removePerson=removePerson;
window.alertFilter="All";window.selectedAlertId=null;
function formatAlertStamp(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return {date:value||"Unknown time",time:""};return {date:date.toLocaleDateString(undefined,{day:"2-digit",month:"short",year:"numeric"}),time:date.toLocaleTimeString(undefined,{hour:"2-digit",minute:"2-digit"})}}
function alertTimeMarkup(value){const stamp=formatAlertStamp(value);return `${esc(stamp.date)}${stamp.time?`<br>${esc(stamp.time)}`:""}`}
function filteredAlertRows(){const all=window.alertRowsData||[],filter=window.alertFilter||"All",query=($("alertSearch")?.value||"").trim().toLowerCase(),sort=$("alertSort")?.value||"newest";return all.filter(a=>(filter==="All"||a.status===filter)&&(!query||(a.source+" "+a.summary+" "+a.reviewer).toLowerCase().includes(query))).sort((a,b)=>{const diff=new Date(a.occurred_at)-new Date(b.occurred_at);return sort==="oldest"?diff:-diff})}
function renderAlertDetail(item){const detail=$("alertDetail");if(!item){detail.innerHTML='<div class="review-empty"><h2>No matching items</h2><p>Try another status filter or search term.</p></div>';return}const stamp=formatAlertStamp(item.occurred_at);const actions=can("review_alerts")?`<form class="review-footer" id="alertActionForm"><label class="review-note-label" for="reviewNoteInput">Reviewer note</label><textarea id="reviewNoteInput" class="review-note-input" maxlength="500" placeholder="Add concise, factual context">${esc(item.review_note||"")}</textarea><div class="hint" style="margin-top:4px">Saving a note keeps the current review status.</div><div class="review-action-bar"><button class="btn" type="button" data-alert-action="note">Save note</button>${item.status!=="Dismissed"?'<button class="btn" type="button" data-alert-action="Dismissed">Dismiss</button>':""}${item.status!=="Escalated"?'<button class="btn" type="button" data-alert-action="Escalated">Escalate</button>':""}${item.status!=="Reviewed"?'<button class="btn primary" type="button" data-alert-action="Reviewed">Mark reviewed</button>':""}${item.status==="Escalated"?'<button class="btn" type="button" onclick="draftAlertWithAI('+Number(item.id)+')">Draft staff message</button>':""}</div></form>`:'<div class="review-footer hint">Read-only access. Contact an administrator if you need review permissions.</div>';detail.innerHTML=`<div class="review-detail-top">${statePill(item.status)}<span class="review-id">Review item #${esc(item.id)}</span></div><h2>${esc(item.summary)}</h2><div class="review-detail-meta"><time datetime="${esc(item.occurred_at)}">${esc(stamp.date)}${stamp.time?` · ${esc(stamp.time)}`:""}</time><span class="review-meta-sep">·</span><span>${esc(item.source)}</span></div><div class="review-detail-block"><h3>Event summary</h3><p>${esc(item.summary)}</p></div><div class="review-facts"><div class="review-fact"><span>Location / source</span><strong>${esc(item.source)}</strong></div><div class="review-fact"><span>Date &amp; time</span><strong>${esc(stamp.date)}${stamp.time?` · ${esc(stamp.time)}`:""}</strong></div></div><div class="review-detail-block"><h3>Latest review</h3><p>${item.reviewer?`Reviewed by ${esc(item.reviewer)}`:"No reviewer decision recorded yet."}${item.review_note?`\n${esc(item.review_note)}`:""}</p></div>${actions}`}
function drawReviewReport(rows){const pie=$("reviewPie"),legend=$("reviewPieLegend"),bars=$("reviewBars"),center=$("reviewPieCenter"),locations=$("reviewLocations");if(!pie||!legend||!bars)return;const colors={"Needs review":"#c45b52",Reviewed:"#176a68",Dismissed:"#8aa39c",Escalated:"#946514"};const order=["Needs review","Reviewed","Dismissed","Escalated"];const counts=Object.fromEntries(order.map(status=>[status,rows.filter(row=>row.status===status).length]));const total=rows.length||1;const radius=68,circ=2*Math.PI*radius;let offset=0;const rings=order.filter(status=>counts[status]).map(status=>{const arc=counts[status]/total*circ;const ring=`<circle cx="100" cy="100" r="${radius}" fill="none" stroke="${colors[status]}" stroke-width="22" stroke-dasharray="${arc.toFixed(2)} ${circ.toFixed(2)}" stroke-dashoffset="-${offset.toFixed(2)}" transform="rotate(-90 100 100)"/>`;offset+=arc;return ring}).join("");pie.innerHTML=`<circle cx="100" cy="100" r="${radius}" fill="none" stroke="#e7eeeb" stroke-width="22"/>${rings}`;if(center)center.innerHTML=`<div><strong>${rows.length}</strong><span>Reviews</span></div>`;legend.innerHTML=order.map(status=>`<span><i style="background:${colors[status]}"></i>${esc(status)} · ${counts[status]}</span>`).join("");const places=new Map();for(const row of rows){const place=row.source||"Unknown place";const item=places.get(place)||{place,open:0,done:0};if(row.status==="Needs review")item.open+=1;else item.done+=1;places.set(place,item)}if(locations)locations.innerHTML=[...places.values()].map(item=>`<div class="loc-chip"><strong>${esc(item.place)}</strong><small>${item.open} open · ${item.done} decided</small></div>`).join("")||'<div class="empty">No review location yet.</div>';const slots=["Night","Morning","Afternoon","Evening"];const slotCounts=Object.fromEntries(slots.map(slot=>[slot,Object.fromEntries(order.map(status=>[status,0]))]));for(const row of rows){const date=new Date(row.occurred_at);const slot=!Number.isNaN(date.getTime())&&slots.includes(timeSlotLabel(date))?timeSlotLabel(date):"Evening";const status=order.includes(row.status)?row.status:"Needs review";slotCounts[slot][status]+=1}const peak=Math.max(1,...slots.map(slot=>order.reduce((sum,status)=>sum+slotCounts[slot][status],0)));bars.className="review-bars";bars.innerHTML=slots.map(slot=>{const count=order.reduce((sum,status)=>sum+slotCounts[slot][status],0);const parts=order.filter(status=>slotCounts[slot][status]).map(status=>`<i style="width:${(slotCounts[slot][status]/peak*100).toFixed(1)}%;background:${colors[status]}" title="${esc(status)}"></i>`).join("");return `<div class="review-bar"><b>${slot}</b><div class="review-bar-track">${parts}</div><span>${count}</span></div>`}).join("")}
function renderAlerts(rows){drawReviewReport(rows);window.alertRowsData=rows;window.alertFilter="All"}
$("alertRows")?.addEventListener("click",event=>{const row=event.target.closest("[data-alert-id]");if(!row)return;window.selectedAlertId=Number(row.dataset.alertId);renderAlerts(window.alertRowsData||[]) });
document.querySelectorAll(".review-filter").forEach(button=>button.addEventListener("click",()=>{window.alertFilter=button.dataset.alertFilter;document.querySelectorAll(".review-filter").forEach(b=>{const active=b===button;b.classList.toggle("active",active);b.setAttribute("aria-selected",String(active))});renderAlerts(window.alertRowsData||[])}));
$("alertSearch")?.addEventListener("input",()=>renderAlerts(window.alertRowsData||[]));
async function saveAlertAction(action){const item=(window.alertRowsData||[]).find(a=>Number(a.id)===Number(window.selectedAlertId));if(!item)return;const note=$("reviewNoteInput").value.trim();if(action==="note"&&!note){toast("Add a short reviewer note before saving.");$("reviewNoteInput").focus();return}const status=action==="note"?item.status:action;try{await api(`/api/alerts/${item.id}`,{method:"PATCH",body:{status,review_note:note}});await loadAll();toast(action==="note"?"Reviewer note saved to the audit log.":`Item marked ${status.toLowerCase()} and logged.`)}catch(e){toast(e.message)}}
$("alertDetail")?.addEventListener("click",event=>{const action=event.target.closest("[data-alert-action]");if(action)saveAlertAction(action.dataset.alertAction)});
function draftAlertWithAI(id){const item=(window.alertRowsData||[]).find(a=>Number(a.id)===Number(id));if(!item||item.status!=="Escalated"){toast("Only a human-escalated review item can be drafted.");return}const summary="Human-escalated incident for staff review.\nSource: "+item.source+"\nTime: "+item.occurred_at+"\nSummary: "+item.summary;$("aiIncidentText").value=summary;go("ai");$("aiIncidentText").focus()}window.draftAlertWithAI=draftAlertWithAI;
async function reviewAlert(id){window.selectedAlertId=Number(id);renderAlerts(window.alertRowsData||[]);$("reviewNoteInput")?.focus()}window.reviewAlert=reviewAlert;
function timeSlotLabel(date){const hour=date.getHours();if(hour<5||hour>=21)return "Night";if(hour<12)return "Morning";if(hour<17)return "Afternoon";return "Evening"}
function drawOverviewReport(staff,watch){const pie=$("overviewPie"),legend=$("overviewPieLegend"),bars=$("overviewBars"),center=$("overviewPieCenter"),locations=$("overviewLocations");if(!pie||!legend||!bars)return;const tracks=[...staff.map(session=>({name:session.name,kind:"Staff",when:session.in,place:session.place||"Unknown place"})),...watch.map(event=>({name:event.person_label.split(" · ")[0],kind:"Alert",when:event.last_seen||event.first_seen,place:event.last_camera||event.first_camera||"Unknown place"}))].map(track=>{const date=new Date(track.when);const known=!Number.isNaN(date.getTime());return {...track,date:known?date.toLocaleDateString(undefined,{year:"numeric",month:"short",day:"2-digit"}):"Unknown date",slot:known?timeSlotLabel(date):"Unknown slot",clock:known?formatAuditTimestamp(track.when):"Unknown time",hour:known?date.getHours()+date.getMinutes()/60:0}}).sort((a,b)=>String(b.when).localeCompare(String(a.when)));const staffCount=tracks.filter(track=>track.kind==="Staff").length,alertCount=tracks.filter(track=>track.kind==="Alert").length,total=tracks.length||1;const radius=68,circ=(2*Math.PI*radius).toFixed(2),staffArc=(staffCount/total*2*Math.PI*radius).toFixed(2),alertArc=(alertCount/total*2*Math.PI*radius).toFixed(2);pie.innerHTML=`<circle cx="100" cy="100" r="${radius}" fill="none" stroke="#e7eeeb" stroke-width="22"/><circle cx="100" cy="100" r="${radius}" fill="none" stroke="#176a68" stroke-width="22" stroke-dasharray="${staffArc} ${circ}" transform="rotate(-90 100 100)"/><circle cx="100" cy="100" r="${radius}" fill="none" stroke="#c45b52" stroke-width="22" stroke-dasharray="${alertArc} ${circ}" stroke-dashoffset="-${staffArc}" transform="rotate(-90 100 100)"/>`;if(center)center.innerHTML=`<div><strong>${tracks.length}</strong><span>Tracks</span></div>`;legend.innerHTML=`<span><i style="background:#176a68"></i>Staff and manager time · ${staffCount}</span><span><i style="background:#c45b52"></i>Whitelist alerts · ${alertCount}</span>`;const places=new Map();for(const track of tracks){const row=places.get(track.place)||{place:track.place,staff:0,alerts:0,dates:new Set()};if(track.kind==="Alert")row.alerts+=1;else row.staff+=1;row.dates.add(track.date);places.set(track.place,row)}if(locations)locations.innerHTML=[...places.values()].map(row=>`<div class="loc-chip"><strong>${esc(row.place)}</strong><small>${row.staff} staff · ${row.alerts} whitelist alerts · ${esc([...row.dates].join(", "))}</small></div>`).join("")||'<div class="empty">No location yet.</div>';bars.innerHTML=tracks.length?tracks.map(track=>`<article class="track-card${track.kind==="Alert"?" alert":""}"><div class="track-mark">${esc(track.name.slice(0,1).toUpperCase())}</div><div><strong>${esc(track.name)}</strong><div class="track-meta"><span>${esc(track.date)}</span><span>${esc(track.slot)}</span><span>${esc(track.clock)}</span><span>${esc(track.place)}</span></div></div><em>${track.kind==="Alert"?"Whitelist alert":"Staff time"}</em><div class="day-ruler" title="When in the day"><i style="left:${Math.max(4,Math.min(96,track.hour/24*100)).toFixed(1)}%"></i></div></article>`).join(""):'<div class="empty">No track is recorded yet.</div>'}
$("recordDeleteRows")?.addEventListener("click",async event=>{const button=event.target.closest("[data-delete-kind]");if(!button)return;const kind=button.dataset.deleteKind;const prompts={staff:"Delete staff and manager sightings on this site? People records stay. Only an administrator can do this.",whitelist:"Delete whitelist sightings and their under-review alerts? People records stay. Only an administrator can do this.",people:"Delete every staff, manager, and whitelist people record, including stored photos? Only an administrator can do this."};if(!confirm(prompts[kind]))return;try{const result=await api("/api/records?kind="+encodeURIComponent(kind),{method:"DELETE"});toast(kind==="people"?`People records deleted: ${result.people}.`:`Deleted ${result.movements} sightings and ${result.alerts} alerts.`);await loadAll()}catch(e){toast(e.message)}});
function renderOverview(devices,alerts,people=[],presence=[],cameraMovements=[]){const recognized=cameraMovements.filter(event=>event.person_label);const staffEvents=recognized.filter(event=>/· (Staff|Manager)$/.test(event.person_label));const watch=recognized.filter(event=>event.person_label.endsWith("· Watchlist"));const staff=staffEvents.map(event=>({name:event.person_label.split(" · ")[0],category:event.person_label.split(" · ")[1]||"",in:event.first_seen,out:event.last_seen||event.first_seen,place:event.last_camera||event.first_camera||""}));if($("overviewIdentifiedCount"))$("overviewIdentifiedCount").textContent=staff.length;if($("overviewWatchCount"))$("overviewWatchCount").textContent=watch.length;drawOverviewReport(staff,watch);if($("overviewIdentified"))$("overviewIdentified").innerHTML=staff.length?staff.slice(0,12).map(session=>`<div class="overview-camera-event"><div class="overview-movement-info"><strong>${esc(session.name)}</strong><small>${esc(session.category)} · In ${esc(formatAuditTimestamp(session.in))} · Session ${esc(formatAuditTimestamp(session.out))} · Last place ${esc(session.place)}</small></div><span class="overview-movement-kind">${statePill("Identified")}</span></div>`).join(""):'<div class="empty">No staff or manager time is recorded yet.</div>';if($("overviewWatchlist"))$("overviewWatchlist").innerHTML=watch.length?watch.slice(0,12).map(event=>`<div class="overview-camera-event"><div class="overview-movement-info"><strong>${esc(event.person_label.split(" · ")[0])}</strong><small>Watchlist · ${esc(formatAuditTimestamp(event.last_seen||event.first_seen))} · ${esc(event.last_camera||event.first_camera)}</small></div><span class="overview-movement-kind">${statePill("Alert")}</span></div>`).join(""):'<div class="empty">No whitelist alert yet.</div>'}
function formatAuditTimestamp(value){const date=new Date(value);if(Number.isNaN(date.getTime()))return value||"Unknown time";return date.toLocaleString(undefined,{year:"numeric",month:"short",day:"2-digit",hour:"2-digit",minute:"2-digit"})}
function renderAudit(rows){$("auditRows").innerHTML=rows.length?rows.map(r=>`<div class="audititem"><b>${esc(r.action)}</b> · ${esc(r.object_type)}${r.object_id?` #${esc(r.object_id)}`:""}<br><span class="muted">${esc(r.actor)} · ${esc(formatAuditTimestamp(r.created_at))}${r.detail?` · ${esc(r.detail)}`:""}</span></div>`).join(""):'<div class="empty">No changes recorded for this project.</div>'}
async function loadMovements(){try{const events=await api("/api/movements");if($("movementRows"))$("movementRows").innerHTML=events.length?events.map(e=>`<tr><td>${esc(e.first_seen)}</td><td>${esc(e.person_label||"—")}</td><td>${esc(e.event_reference)}</td><td>${statePill(e.direction||"Unknown")}</td><td>${esc(e.first_camera)}</td><td>${esc(e.last_camera)}</td><td>${esc(e.last_seen)}</td><td>${statePill(e.review_status)}</td></tr>`).join(""):'<tr><td colspan="8" class="empty">No face matches yet. Save an RTSP URL on a camera, or upload one frame on this page.</td></tr>';renderOverview([],[],[],[],events)}catch(e){toast(e.message)}}
async function scanFrame(deviceId,file){const headers={"X-CSRF-Token":csrfToken,"X-Casino-Project":activeProject};let body=file;if(file){headers["Content-Type"]=file.type||"image/jpeg"}else{headers["Content-Type"]="application/json";body=JSON.stringify({live:true})}const response=await fetch("/api/devices/"+deviceId+"/scan",{method:"POST",headers,credentials:"same-origin",body});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||"Scan failed");return data}
function fillScanDevices(rows){const select=$("scanDevice");if(!select)return;const current=select.value;select.innerHTML=rows.length?rows.map(d=>`<option value="${d.id}">${esc(d.name)}${d.stream_configured?" · stream saved":""}</option>`).join(""):'<option value="">No camera saved</option>';if(current)select.value=current}
async function saveUploadedPerson(file,name,category){const saved=await api("/api/people",{method:"POST",body:{display_name:name,category,position:"Uploaded photo",record_reference:"",record_owner:currentUsername||"Local operator",purpose:"Photo uploaded and stored in the local database.",review_date:new Date(Date.now()+365*24*60*60*1000).toISOString().slice(0,10)}});await uploadProfilePhoto(saved.id,file);return saved}
$("scanForm")?.addEventListener("submit",async e=>{e.preventDefault();const deviceId=$("scanDevice").value;const file=$("scanFile").files[0];const name=$("scanPersonName").value.trim();const category=$("scanPersonCategory").value;if(!file){$("scanResult").textContent="Choose a photo file. It is saved on People and matched.";return}if(!isRosterPhoto(file)){$("scanResult").textContent="Choose a JPEG or PNG photo up to 5 MB.";return}$("scanResult").textContent="Saving the person and photo…";try{await saveUploadedPerson(file,name,category);const result=await scanFrame(deviceId,file);$("scanResult").textContent=result.matched?`Saved on People. ${result.person} (${result.category}) ${result.category==="Watchlist"?"under review":"identified"} at ${result.seen_at}.`:"Saved on People. Open the People tab to see the record.";$("scanFile").value="";$("scanPersonName").value="";await loadMovements();await loadAll();go("people")}catch(err){$("scanResult").textContent=err.message}});
let macStream=null,macWatchTimer=null,macWatchBusy=false,macSeen={};
function stopMacWatch(){if(macWatchTimer){clearInterval(macWatchTimer);macWatchTimer=null}}
async function watchLiveFace(){const deviceId=$("scanDevice")?.value;if(macWatchBusy||!deviceId||!macStream||!$("macVideo")?.videoWidth)return;macWatchBusy=true;try{const blob=await captureMacJpeg();const file=new File([blob],"live-frame.jpg",{type:"image/jpeg"});const result=await scanFrame(deviceId,file);if(!result.matched){$("scanResult").textContent="Scanning continuously. No stored face in this frame.";return}const key=result.person||"";const now=Date.now();const same=result.continued||(macSeen[key]&&now-macSeen[key]<8000);macSeen[key]=now;const whitelist=result.category==="Watchlist";$("scanResult").textContent=whitelist?(same?`Still watching ${result.person}. Whitelist alert stays on Overview.`:`Whitelist alert recorded. ${result.person}. Opening Overview.`):(same?`Still watching ${result.person}. Staying on this camera.`:`Time recorded. ${result.person}. Staying on this camera.`);if(!same||now-(macSeen[key+"-shown"]||0)>3000){macSeen[key+"-shown"]=now;await loadMovements();await loadAll()}if(whitelist&&!same)go("overview")}catch(err){$("scanResult").textContent=err.message}finally{macWatchBusy=false}}
async function openMacCamera(){if(!navigator.mediaDevices?.getUserMedia)throw new Error("This browser cannot open the Mac camera.");if(macStream)return;macStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user",width:{ideal:640}},audio:false});const video=$("macVideo");video.srcObject=macStream;await video.play()}
function captureMacJpeg(){const video=$("macVideo");if(!video.videoWidth)throw new Error("Open the Mac camera and wait until the picture appears.");const canvas=$("macCanvas");canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext("2d").drawImage(video,0,0);return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error("Could not capture a frame")),"image/jpeg",0.92))}
$("macCameraStart")?.addEventListener("click",async()=>{try{$("scanResult").textContent="Opening the Mac camera…";await openMacCamera();$("scanResult").textContent="Live camera is scanning continuously. It stays on this camera.";stopMacWatch();macSeen={};macWatchTimer=setInterval(watchLiveFace,1000);setTimeout(watchLiveFace,400)}catch(err){$("scanResult").textContent=err.message||"Camera permission was blocked."}});
$("macCameraStore")?.addEventListener("click",async()=>{try{await openMacCamera();$("scanResult").textContent="Storing the face from the Mac camera…";const blob=await captureMacJpeg();const people=await api("/api/people");let person=people.find(p=>p.record_reference==="MAC-CAM-TEST");if(!person){person=await api("/api/people",{method:"POST",body:{display_name:"Mac camera test",category:"Staff",position:"Camera test",record_reference:"MAC-CAM-TEST",record_owner:"Local test",purpose:"Photo captured from this Mac camera for a local recognition test.",review_date:"2026-12-31"}})}const file=new File([blob],"mac-camera.jpg",{type:"image/jpeg"});await uploadProfilePhoto(person.id,file);$("scanResult").textContent="Face stored on the Mac camera test record. Stay in frame, then choose Recognize this face.";await loadAll()}catch(err){$("scanResult").textContent=err.message}});
$("macCameraRecognize")?.addEventListener("click",async()=>{try{await watchLiveFace()}catch(err){$("scanResult").textContent=err.message}});
async function loadOutbox(){try{renderOutbox(await api("/api/automation/outbox"))}catch(e){toast(e.message)}}
function renderOutbox(rows){const pending=rows.filter(e=>e.delivery_status==="Queued").length;$("outboxCount").textContent=`${pending} queued · not transmitted`;$("outboxRows").innerHTML=rows.length?rows.map(e=>`<article class="lane-card"><div><strong>${esc(e.event_type)}</strong><small>${esc(formatAuditTimestamp(e.created_at))} · ${esc(e.id)}</small></div>${statePill(e.delivery_status)}</article>`).join(""):'<div class="empty">No events queued yet.</div>'}
async function loadDiscoverySettings(){try{const cfg=await api("/api/discovery/settings");$("discoveryEnabled").checked=!!cfg.enabled;$("discoveryCidrs").value=JSON.parse(cfg.cidrs||"[]").join(", ");$("discoveryState").textContent=cfg.enabled?"Enabled · manual run":"Disabled";$("discoveryState").className=`pill ${cfg.enabled?"wait":""}`;$("discoveryLast").textContent=cfg.last_result?`Last run: ${cfg.last_result}`:"Discovery has not been run."}catch(e){toast(e.message)}}

function formObject(form){const data=Object.fromEntries(new FormData(form).entries());if(form.id==="deviceForm")data.monitoring_purposes=new FormData(form).getAll("monitoring_purposes");return data}
$("sourceMode").addEventListener("change",()=>{if($("sourceMode").value==="Standalone camera"){$("deviceKind").value="Camera";$("deviceForm").elements.coverage_role.value="Entrance"}});
$("deviceForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget;try{await api("/api/devices",{method:"POST",body:formObject(form)});form.reset();closeModal("deviceModal");toast("Camera source saved under the selected project. Connection remains unverified.");await loadAll()}catch(err){toast(err.message)}});
function isRosterPhoto(file){const type=(file.type||"").toLowerCase();const name=(file.name||"").toLowerCase();const allowed=type==="image/jpeg"||type==="image/jpg"||type==="image/pjpeg"||type==="image/png"||/\.(jpe?g|png)$/.test(name);return allowed&&file.size>0&&file.size<=5*1024*1024}
function photoContentType(file){return (file.type||"").toLowerCase()==="image/png"||(file.name||"").toLowerCase().endsWith(".png")?"image/png":"image/jpeg"}
async function uploadProfilePhoto(personId,file){const response=await fetch(`/api/people/${personId}/photo`,{method:"POST",headers:{"Content-Type":photoContentType(file),"X-CSRF-Token":csrfToken,"X-Casino-Project":activeProject},credentials:"same-origin",body:file});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||"Photo upload failed")}
$("personForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,file=$("newPersonPhoto").files[0];if(file&&!isRosterPhoto(file)){toast("Choose a JPEG or PNG photo up to 5 MB.");return}try{const saved=await api("/api/people",{method:"POST",body:formObject(form)});let message="People record saved. The photo is not added to Overview.";if(file){try{await uploadProfilePhoto(saved.id,file)}catch(photoError){message="The record was saved, but the photo was not stored: "+photoError.message}}form.reset();closeModal("personModal");toast(message);await loadAll();go("people")}catch(err){toast(err.message)}});
$("alertForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,d=formObject(form);if(d.occurred_at)d.occurred_at=new Date(d.occurred_at).toISOString();else delete d.occurred_at;try{await api("/api/alerts",{method:"POST",body:d});form.reset();closeModal("alertModal");toast("Manual review item added.");await loadAll()}catch(err){toast(err.message)}});
$("projectForm").addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget;try{const p=await api("/api/projects",{method:"POST",body:formObject(form),project:false});form.reset();closeModal("projectModal");activeProject=String(p.id);await loadProjects();toast("CCTV project created.")}catch(err){toast(err.message)}});
$("discoveryForm").addEventListener("submit",async e=>{e.preventDefault();const cidrs=$("discoveryCidrs").value.split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);try{await api("/api/discovery/settings",{method:"POST",body:{enabled:$("discoveryEnabled").checked,cidrs}});toast("Discovery settings saved for this project.");await loadDiscoverySettings()}catch(err){toast(err.message)}});
$("discoverBtn").addEventListener("click",async()=>{if(!confirm("Send ONVIF discovery probes only on the private CCTV subnets saved for this project? Found devices will be listed as unverified candidates; no video connection will be opened."))return;$("discoverBtn").disabled=true;$("discoverBtn").textContent="Discovering…";try{const result=await api("/api/discovery/run",{method:"POST",body:{}});toast(result.result);await loadAll();await loadDiscoverySettings()}catch(err){toast(err.message)}finally{$("discoverBtn").disabled=false;$("discoverBtn").textContent="Find ONVIF devices"}});


async function loadUsers(){try{const rows=await api("/api/users",{project:false});$("userRows").innerHTML=rows.length?rows.map(u=>`<article class="lane-card"><div><strong>${esc(u.username)}${u.is_current_user?" · You":""}</strong><small>${u.permissions.map(p=>esc(permissionLabels[p]||p)).join(" · ")} · ${esc(u.created_at)}</small></div><div>${u.active?statePill("Active"):statePill("Disabled")}<button class="btn" data-edit-user="${u.id}">Edit</button></div></article>`).join(""):'<div class="empty">No accounts.</div>'}catch(e){toast(e.message)}}
$("userRows").addEventListener("click",event=>{const button=event.target.closest("[data-edit-user]");if(button)editUser(Number(button.dataset.editUser))});
function renderPermissionChoices(selected){$("permissionChoices").innerHTML=Object.entries(permissionLabels).map(([key,label])=>"<label class=hint><input type=checkbox name=permissions value="+key+" "+(selected.includes(key)?"checked":"")+">"+esc(label)+"</label>").join("")}
function newUser(){const f=$("userForm");f.reset();f.elements.id.value="";f.elements.username.disabled=false;$("userModalTitle").textContent="Create account";$("userPasswordField").classList.remove("hidden");$("userActiveField").classList.add("hidden");f.elements.password.required=true;renderPermissionChoices(["view_dashboard"]);modal("userModal")}
async function editUser(id){try{const rows=await api("/api/users",{project:false});const u=rows.find(x=>x.id===id);if(!u)return;const f=$("userForm");f.reset();f.elements.id.value=u.id;f.elements.username.value=u.username;f.elements.username.disabled=true;f.elements.active.checked=!!u.active;$("userModalTitle").textContent="Edit "+u.username;$("userPasswordField").classList.add("hidden");$("userActiveField").classList.remove("hidden");f.elements.password.required=false;renderPermissionChoices(u.permissions);modal("userModal")}catch(e){toast(e.message)}}window.newUser=newUser;window.editUser=editUser;
$("userForm").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,id=f.elements.id.value,permissions=[...f.querySelectorAll("[name=permissions]:checked")].map(x=>x.value);const body={permissions};try{if(id){body.active=f.elements.active.checked;await api("/api/users/"+id,{method:"PATCH",body,project:false})}else{body.username=f.elements.username.value.trim();body.password=f.elements.password.value;await api("/api/users",{method:"POST",body,project:false})}closeModal("userModal");f.reset();f.elements.username.disabled=false;toast("Account saved and logged.");await loadUsers()}catch(err){toast(err.message)}});
async function downloadBackup(name){try{const response=await fetch("/api/backups/download?name="+encodeURIComponent(name),{credentials:"same-origin"});if(!response.ok){const data=await response.json();throw new Error(data.error||"Download failed")}const blob=await response.blob(),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}catch(e){toast(e.message)}}
async function loadBackups(){try{const rows=await api("/api/backups",{project:false});$("backupRows").innerHTML=rows.length?rows.map(b=>`<article class="lane-card"><div><strong>${esc(b.name)}</strong><small>${esc(b.modified)} · ${b.size<1024?b.size+" B":(b.size/1024).toFixed(1)+" KB"}</small></div><button class="btn" onclick="downloadBackup(&quot;${esc(b.name)}&quot;)">Download</button></article>`).join(""):'<div class="empty">No snapshots yet.</div>'}catch(e){toast(e.message)}}window.downloadBackup=downloadBackup;
$("createBackupBtn").addEventListener("click",async()=>{const b=$("createBackupBtn");b.disabled=true;try{const result=await api("/api/backups",{method:"POST",body:{},project:false});toast("Snapshot created: "+result.name);await loadBackups()}catch(e){toast(e.message)}finally{b.disabled=false}});
async function downloadPeopleWorkbook(path,filename){try{const response=await fetch(path,{headers:{"X-Casino-Project":activeProject},credentials:"same-origin"});if(!response.ok){let data={};try{data=await response.json()}catch{}throw new Error(data.error||"Workbook download failed")}const blob=await response.blob();const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}catch(e){toast(e.message)}}
$("peopleTemplateBtn").addEventListener("click",()=>downloadPeopleWorkbook("/api/people/template.xlsx","people-import-template.xlsx"));
$("peopleExportBtn").addEventListener("click",()=>downloadPeopleWorkbook("/api/people/export.xlsx","people-export.xlsx"));
$("peopleImportFile").addEventListener("change",async event=>{const file=event.target.files[0];event.target.value="";if(!file)return;const status=$("importStatus");status.textContent="";if(file.size>20*1024*1024){toast("Workbook exceeds the 20 MB limit.");return}if(!file.name.toLowerCase().endsWith(".xlsx")){toast("Choose an .xlsx workbook.");return}if(!confirm("Import all valid rows from this workbook into the selected project? Imported records will start as Pending review."))return;status.innerHTML="<div class='import-result'><strong>Checking workbook…</strong><span>Rows are checked before anything is saved.</span></div>";try{const response=await fetch("/api/people/import.xlsx",{method:"POST",headers:{"Content-Type":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","X-CSRF-Token":csrfToken,"X-Casino-Project":activeProject},credentials:"same-origin",body:file});let data={};try{data=await response.json()}catch{}if(!response.ok){const issues=data.row_errors||[];const list=issues.slice(0,20).map(item=>"<li>Row "+esc(item.row)+": "+esc(item.error)+"</li>").join("");status.innerHTML="<div class='import-result error'><strong>"+esc(data.error||"Import failed")+"</strong><span>No rows were saved. "+(data.error_count?esc(data.error_count)+" row(s) need correction.":"Check the workbook and try again.")+"</span>"+(list?"<ul>"+list+"</ul>":"")+(issues.length>20?"<span>Showing the first 20 row errors. The server returned up to 200 details.</span>":"")+"</div>";toast("Import stopped. Review the row errors below.");return}status.innerHTML="<div class='import-result success'><strong>Import complete</strong><span>"+esc(data.message)+"</span></div>";toast(data.message);await loadAll()}catch(e){status.innerHTML="<div class='import-result error'><strong>Import failed</strong><span>"+esc(e.message)+"</span></div>";toast(e.message)}});
const typeSelectFull=typeSelect;typeSelect=function(d){return can("manage_devices")?typeSelectFull(d):esc(d.device_kind)};
const renderPeopleFull=renderPeople;renderPeople=function(rows){renderPeopleFull(rows);if(!can("manage_people"))document.querySelectorAll("#peopleRows button").forEach(button=>button.remove())};
