async function loadOpenAIStatus(){try{const status=await api("/api/ai/status");$("openaiModel").textContent="Model: "+status.model;$("openaiState").textContent=status.configured?"Key configured · not tested":"Key not configured";$("openaiState").className="pill "+(status.configured?"wait":"");$("openaiStatusText").textContent=status.configured?"Press Check OpenAI connection to confirm key and model access. No prompt or image is sent by this check.":"Set OPENAI_API_KEY in the server environment and restart the app. Never enter the key in this page."}catch(e){$("openaiState").textContent="Unavailable";$("openaiStatusText").textContent=e.message}}
$("openaiCheckBtn").addEventListener("click",async()=>{const button=$("openaiCheckBtn");button.disabled=true;button.textContent="Checking…";try{const result=await api("/api/ai/check",{method:"POST",body:{}});$("openaiState").textContent="Connected · "+result.model;$("openaiState").className="pill ok";$("openaiStatusText").textContent=result.message;toast("OpenAI connection check passed.")}catch(e){$("openaiState").textContent="Connection failed";$("openaiState").className="pill alert";$("openaiStatusText").textContent=e.message}finally{button.disabled=false;button.textContent="Check OpenAI connection"}});
$("aiDraftForm").addEventListener("submit",async e=>{e.preventDefault();const button=$("aiDraftBtn");button.disabled=true;button.textContent="Drafting…";$("aiDraftError").textContent="";$("aiDraftResult").classList.add("hidden");try{const result=await api("/api/ai/draft",{method:"POST",body:{incident_text:$("aiIncidentText").value.trim()}});$("aiDraftText").textContent=result.draft;$("aiDraftResult").classList.remove("hidden");toast("Draft ready for staff review. It was not sent.")}catch(err){$("aiDraftError").textContent=err.message}finally{button.disabled=false;button.textContent="✧ Draft staff message"}});
$("copyAiDraftBtn").addEventListener("click",async()=>{try{await navigator.clipboard.writeText($("aiDraftText").textContent);toast("Draft copied. It has not been sent.")}catch{toast("Clipboard access is unavailable.")}});
initialize();
